document.addEventListener('click', function(e){
        if (!e.target || !e.target.closest) return;
        var b = e.target.closest('#dayViewMode button');
        if (!b) return;
        var mode = b.getAttribute('data-mode');
        if (mode !== 'task' && mode !== 'employee') return;
        var st = window.__trkState;
        if (!st) return;
        st.dayViewMode = mode;
        try { localStorage.setItem('tracker_day_view', mode); } catch (er) {}

